process.stdin.resume();
process.stdin.setEncoding('utf8');

let inputData = '';
process.stdin.on('data', d => inputData += d);
process.stdin.on('end', () => {
    const parts = inputData.trim().split(/\s+/).map(Number);
    const n = parts[0], m = parts[1];
    console.log(solve(n, m));
});

function solve(n, m) {
    let R = Math.min(n, m);
    let C = Math.max(n, m);
    let full = (1 << R) - 1;
    let size = full + 1;

    function popcount(x) {
        let c = 0;
        while (x) {
            c += x & 1;
            x >>= 1;
        }
        return c;
    }

    function selfVert(S) {
        let v = S | (S << 1) | (S >> 1);
        return v & full;
    }

    // dp[S * size + cov] = min cost
    let dp = new Array(size * size).fill(Infinity);

    for (let S = 0; S <= full; S++) {
        let cov = selfVert(S);
        let idx = S * size + cov;
        let cost = popcount(S);
        if (cost < dp[idx]) dp[idx] = cost;
    }

    for (let c = 1; c < C; c++) {
        let ndp = new Array(size * size).fill(Infinity);
        for (let Sp = 0; Sp <= full; Sp++) {
            for (let cov = 0; cov <= full; cov++) {
                let cprev = dp[Sp * size + cov];
                if (cprev === Infinity) continue;
                for (let Sc = 0; Sc <= full; Sc++) {
                    let newCovPrev = cov | Sc;
                    if (newCovPrev !== full) continue;
                    let covCur = selfVert(Sc) | Sp;
                    let cost = cprev + popcount(Sc);
                    let idx = Sc * size + covCur;
                    if (cost < ndp[idx]) ndp[idx] = cost;
                }
            }
        }
        dp = ndp;
    }

    let ans = Infinity;
    for (let S = 0; S <= full; S++) {
        let idx = S * size + full;
        if (dp[idx] < ans) ans = dp[idx];
    }

    return n * m - ans;
}
